1|// Step: re-split scenes where the dominant emotion changes strongly
2|// along the text. Reads book.json and analysis.json, rewrites
3|// scenes.json and analysis.json. Reuses only when the recorded
4|// resplit input matches the current scene ranges.
5|// A Muse resplit failure keeps the scene whole and lands in muse_failures.
6|import { readFileSync, writeFileSync } from "node:fs";
7|import { join } from "node:path";
8|import { renormalize8 } from "../core/emotion";
9|import { countWords } from "../core/reader";
10|import {
11|  RESPLIT_ASK_MARGIN,
12|  RESPLIT_AUTO_MARGIN,
13|  buildWindows,
14|  isResplitCandidate,
15|  meanVector,
16|  planSplits,
17|  splitIds,
18|  topOf,
19|} from "../core/resplit";
20|import type { ResplitWindow, SplitCall } from "../core/resplit";
21|import { validateBookCoverage } from "../core/scenes";
22|import type { AnalyzedScene, Book, EmotionId, Scene, SceneEmotion } from "../core/types";
23|import { classifyInputOf, decide, resplitInputOf, resplitKeys } from "./freshness";
24|import { classifyScene } from "./classify";
25|import type { ClassifyMetaUsage } from "./classify";
26|import type { StepCtx } from "./ingest";
27|import { runPool } from "./http";
28|import type { JevClient } from "./jev";
29|import type { MetaClient } from "./meta";
30|import { jevCostUsd, metaCostUsd } from "./prices";
31|
32|const DECISION_SCHEMA = {
33|  type: "object",
34|  properties: { split: { type: "boolean" }, reason: { type: "string" } },
35|  required: ["split", "reason"],
36|  additionalProperties: false,
37|};
38|
39|const TITLES_SCHEMA = {
40|  type: "object",
41|  properties: {
42|    parts: {
43|      type: "array",
44|      items: {
45|        type: "object",
46|        properties: {
47|          start_n: { type: "number" },
48|          end_n: { type: "number" },
49|          title: { type: "string" },
50|          summary: { type: "string" },
51|          characters: { type: "array", items: { type: "string" } },
52|        },
53|        required: ["start_n", "end_n", "title", "summary", "characters"],
54|        additionalProperties: false,
55|      },
56|    },
57|  },
58|  required: ["parts"],
59|  additionalProperties: false,
60|};
