62|export interface ResplitEntry {
63|  from: string;
64|  at_n: number;
65|  margin: number;
66|  window_left: EmotionId;
67|  window_right: EmotionId;
68|  final_left: EmotionId | null;
69|  final_right: EmotionId | null;
70|  decided_by: "rule" | "muse";
71|  reason?: string;
72|}
73|
74|export interface ResplitRejected {
75|  from: string;
76|  at_n: number;
77|  margin: number;
78|  window_left: EmotionId;
79|  window_right: EmotionId;
80|  reason: string;
81|}
82|
83|export interface ResplitMergedBack {
84|  from: string;
85|  top: EmotionId | null;
86|}
87|
88|interface Usage {
89|  jevRequests: number;
90|  jevInputTokens: number;
91|  jevOutputTokens: number;
92|  meta: ClassifyMetaUsage;
93|}
94|
95|function newUsage(model: string): Usage {
96|  return { jevRequests: 0, jevInputTokens: 0, jevOutputTokens: 0, meta: { model, requests: 0, promptTokens: 0, cachedTokens: 0, completionTokens: 0, costUsd: 0 } };
97|}
98|
99|export interface ResplitWindowFailure {
100|  from: string;
101|  reason: string;
102|}
103|
104|function museFailureReason(err: unknown): string {
105|  const msg = err instanceof Error ? err.message : String(err);
106|  const reason = msg
107|    .replace(/https?:\/\/\S+/g, "[url]")
108|    .replace(/www\.\S+/g, "[url]")
109|    .replace(/(?:bearer|api[_-]?key|token|secret|password)\s*[:=]\s*\S+/gi, "$1 [redacted]")
110|    .replace(/[A-Za-z0-9_\-+/=]{24,}/g, "[redacted]")
111|    .replace(/\s+/g, " ")
112|    .trim()
113|    .slice(0, 200);
114|  return reason || "unknown-error";
115|}
116|
117|function trackMeta(usage: Usage, result: { promptTokens: number; cachedTokens: number; completionTokens: number }): void {
118|  usage.meta.requests += 1;
119|  usage.meta.promptTokens += result.promptTokens;
120|  usage.meta.cachedTokens += result.cachedTokens;
121|  usage.meta.completionTokens += result.completionTokens;
122|}
123|
124|export async function runResplit(ctx: StepCtx, deps: { jev: JevClient; meta: MetaClient }): Promise<AnalyzedScene[]> {
125|  const book = JSON.parse(readFileSync(join(ctx.dir, "book.json"), "utf8")) as Book;
126|  const scenesFile = JSON.parse(readFileSync(join(ctx.dir, "scenes.json"), "utf8")) as {
127|    bookId: string;
128|    textVersion: string;
129|    scenes: Scene[];
130|    provenance: { meta: { model: string; requests: number; prompt_tokens: number; cached_tokens: number; completion_tokens: number; cost_usd: number } };
131|  };
132|  const analysisFile = JSON.parse(readFileSync(join(ctx.dir, "analysis.json"), "utf8")) as {
133|    bookId: string;
134|    textVersion: string;
135|    scenes: AnalyzedScene[];
136|    provenance: {
137|      date: string;
138|      jev: { model: string; requests: number; input_tokens: number; output_tokens: number; cost_usd: number };
139|      meta: { model: string; requests: number; prompt_tokens: number; cached_tokens: number; completion_tokens: number; cost_usd: number };
140|      total_cost_usd: number;
141|      resplit?: unknown;
142|    };
143|  };
144|  const keys = resplitKeys(ctx.dir);
145|  if (decide(ctx.force, keys.recorded, keys.current).reuse) {
146|    return analysisFile.scenes;
147|  }
148|  const usage = newUsage(deps.meta.model);
149|  const byN = new Map(book.paragraphs.map((p) => [p.n, p.text]));
150|  const chapterTitle = new Map(book.chapters.map((c) => [c.ch, c.title]));
151|  const wordsOf = (scene: { start_n: number; end_n: number }): number => {
152|    let words = 0;
153|    for (let n = scene.start_n; n <= scene.end_n; n++) words += countWords(byN.get(n) ?? "");
154|    return words;
155|  };
156|  const candidates = analysisFile.scenes.filter((s) => isResplitCandidate(wordsOf(s), s.final));
157|  let windowsClassified = 0;
158|  const windowFailures: ResplitWindowFailure[] = [];
159|  const museFailures: { from: string; reason: string }[] = [];
160|  const rejected: ResplitRejected[] = [];
161|  const mergedBack: ResplitMergedBack[] = [];
162|
163|  const splitScenes = await runPool(candidates, 4, async (scene) => {
164|    const paragraphs = book.paragraphs.filter((p) => p.n >= scene.start_n && p.n <= scene.end_n);
165|    const spans = buildWindows(paragraphs);
166|    const windows: ResplitWindow[] = [];
167|    for (const span of spans) {
168|      const text = paragraphs.filter((p) => p.n >= span.startN && p.n <= span.endN).map((p) => p.text).join("\n");
169|      let result;
170|      try {
171|        result = await deps.jev.classify({ book: book.title, chapter: chapterTitle.get(scene.ch) ?? "", sceneTitle: scene.title, scene: text });
172|      } catch (err) {
173|        windowFailures.push({ from: scene.id, reason: museFailureReason(err) });
174|        return null;
175|      }
176|      usage.jevRequests += 1;
177|      usage.jevInputTokens += result.input_tokens;
178|      usage.jevOutputTokens += result.output_tokens;
179|      const { unknown: _dropped, ...rest } = result.vector;
180|      const vector = renormalize8(rest);
181|      if (vector === null) {
182|        windowFailures.push({ from: scene.id, reason: "null-vector" });
183|        return null;
184|      }
185|      windows.push({ ...span, vector });
186|      windowsClassified += 1;
187|    }
188|    if (windows.length < 2) return null;
189|    const taken: { call: SplitCall; by: "rule" | "muse" }[] = [];
190|    const reasons = new Map<number, string>();
191|    let cuts: number[];
192|    try {
193|      cuts = await planSplits(
194|        windows,
195|        async (call) => {
196|          const boundaryN = windows[call.index]?.startN ?? 0;
197|          const before = paragraphs.filter((p) => p.n < boundaryN).slice(-2);
198|          const after = paragraphs.filter((p) => p.n >= boundaryN).slice(0, 2);
199|          const left = meanVector(windows.slice(0, call.index));
200|          const right = meanVector(windows.slice(call.index));
201|          const result = await deps.meta.completeJson({
202|            system: "You judge whether a scene needs two music tracks. Answer with JSON only.",
203|            user:
204|              `Scene "${scene.title}" may change mood at paragraph ${windows[call.index]?.startN}. ` +
205|              `Left mood ${call.left} ${JSON.stringify(left)}, right mood ${call.right} ${JSON.stringify(right)}. ` +
206|              `Split only when the dominant feeling changes strongly and stays changed, not for a mixed blend. ` +
207|              `Before: ${before.map((p) => `[${p.n}] ${p.text}`).join("\n")}\nAfter: ${after.map((p) => `[${p.n}] ${p.text}`).join("\n")}`,
208|            schemaName: "resplit_decision",
209|            schema: DECISION_SCHEMA,
210|          });
211|          trackMeta(usage, result);
212|          const data = result.data as { split?: unknown; reason?: unknown };
213|          const split = data.split === true;
214|          const reason = String(data.reason ?? "");
215|          if (split) reasons.set(call.index, reason);
216|          else rejected.push({ from: scene.id, at_n: boundaryN, margin: call.margin, window_left: call.left, window_right: call.right, reason });
217|          return split;
218|        },
219|        (call, by) => taken.push({ call, by }),
220|      );
221|    } catch (err) {
222|      museFailures.push({ from: scene.id, reason: museFailureReason(err) });
223|      return null;
224|    }
225|    if (cuts.length === 0) return null;
226|    const bounds = [0, ...cuts, windows.length];
227|    const ranges = bounds.slice(1).map((end, i) => ({ startN: windows[bounds[i] ?? 0]?.startN ?? 0, endN: windows[end - 1]?.endN ?? 0 }));
228|    let parts: { start_n: number; end_n: number; title: string; summary: string; characters: unknown }[];
229|    try {
230|      const result = await deps.meta.completeJson({
231|        system: "You split a book scene into ordered parts. Answer with JSON only, English titles in the style of the existing scene titles.",
232|        user:
233|          `Scene "${scene.title}" (${scene.id}, summary: ${scene.summary}) splits into ${ranges.length} parts. ` +
234|          `Give each part start_n, end_n, title, summary, and characters.\n` +
235|          ranges.map((r, i) => `PART ${i + 1} [${r.startN}..${r.endN}]:\n${paragraphs.filter((p) => p.n >= r.startN && p.n <= r.endN).map((p) => `[${p.n}] ${p.text}`).join("\n")}`).join("\n"),
236|        schemaName: "resplit_titles",
237|        schema: TITLES_SCHEMA,
238|      });
239|      trackMeta(usage, result);
240|      parts = (result.data as { parts?: { start_n: number; end_n: number; title: string; summary: string; characters: unknown }[] }).parts ?? [];
241|      if (parts.length !== ranges.length || parts.some((p, i) => p.start_n !== ranges[i]?.startN || p.end_n !== ranges[i]?.endN)) {
242|        throw new Error("titles do not cover the split ranges");
243|      }
244|    } catch (err) {
245|      museFailures.push({ from: scene.id, reason: museFailureReason(err) });
246|      return null;
247|    }
248|    const bases = parts.map((part) => ({
249|      ch: scene.ch,
250|      start_n: part.start_n,
251|      end_n: part.end_n,
252|      title: part.title,
253|      summary: part.summary,
254|      characters: Array.isArray(part.characters) ? part.characters.map(String) : [],
255|    }));
256|    const analyzed = await runPool(bases, 4, async (base) => {
257|      const text = paragraphs.filter((p) => p.n >= base.start_n && p.n <= base.end_n).map((p) => p.text).join("\n");
258|      const emotion = await classifyScene({ id: "", ...base }, text, book.title, chapterTitle.get(scene.ch) ?? "", deps, usage.meta);
259|      if (emotion.jev) {
260|        usage.jevRequests += 1;
261|        usage.jevInputTokens += emotion.jev.input_tokens;
262|        usage.jevOutputTokens += emotion.jev.output_tokens;
263|      }
264|      return emotion;
265|    });
266|    // Merge adjacent parts whose re-classified top emotion agrees; a
267|    // null final never merges. One extra classify per merged group.
268|    const tops = analyzed.map((e) => (e.final ? topOf(e.final.vector).id : null));
269|    const groups: number[][] = [];
270|    for (let i = 0; i < bases.length; i++) {
271|      const last = groups[groups.length - 1];
272|      const prev = last ? tops[last[last.length - 1] ?? -1] : undefined;
273|      const top = tops[i];
274|      if (last && top !== null && top === prev) last.push(i);
275|      else groups.push([i]);
276|    }
277|    if (groups.length === 1 && bases.length > 1) {
278|      mergedBack.push({ from: scene.id, top: tops[0] ?? null });
279|      return null;
280|    }
281|    const finals: { base: (typeof bases)[number]; emotion: SceneEmotion }[] = [];
282|    for (const group of groups) {
283|      if (group.length === 1) {
284|        const i = group[0] ?? 0;
285|        finals.push({ base: bases[i]!, emotion: (analyzed[i] ?? { jev: null, muse_override: null, final: null, error: "missing part emotion" }) as SceneEmotion });
286|        continue;
287|      }
288|      const first = bases[group[0] ?? 0]!;
289|      const lastBase = bases[group[group.length - 1] ?? 0]!;
290|      const base = { ...first, start_n: first.start_n, end_n: lastBase.end_n };
291|      const text = paragraphs.filter((p) => p.n >= base.start_n && p.n <= base.end_n).map((p) => p.text).join("\n");
292|      const emotion = await classifyScene({ id: "", ...base }, text, book.title, chapterTitle.get(scene.ch) ?? "", deps, usage.meta);
293|      if (emotion.jev) {
294|        usage.jevRequests += 1;
295|        usage.jevInputTokens += emotion.jev.input_tokens;
296|        usage.jevOutputTokens += emotion.jev.output_tokens;
297|      }
298|      finals.push({ base, emotion });
299|      mergedBack.push({ from: scene.id, top: emotion.final ? topOf(emotion.final.vector).id : null });
300|    }
301|    const ids = splitIds(scene.id, finals.length);
302|    const byCut = new Map(taken.map((t) => [t.call.index, t]));
303|    const finalTops = finals.map((f) => (f.emotion.final ? topOf(f.emotion.final.vector).id : null));
304|    // One entry per surviving cut; the window tops picked the cut and
305|    // the final tops are what the stored parts re-classified to.
306|    const entries: ResplitEntry[] = [];
307|    let start = 0;
308|    for (let g = 0; g + 1 < groups.length; g++) {
309|      const end = start + (groups[g]?.length ?? 0);
310|      const cutIndex = bounds[end] ?? 0;
311|      const call = byCut.get(cutIndex);
312|      const reason = reasons.get(cutIndex);
313|      entries.push({
314|        from: scene.id,
315|        at_n: finals[g + 1]?.base.start_n ?? 0,
316|        margin: call?.call.margin ?? 0,
317|        window_left: call?.call.left ?? "calma",
318|        window_right: call?.call.right ?? "calma",
319|        final_left: finalTops[g] ?? null,
320|        final_right: finalTops[g + 1] ?? null,
321|        decided_by: call?.by ?? "rule",
322|        ...(reason ? { reason } : {}),
323|      });
324|      start = end;
325|    }
326|    return {
327|      scene,
328|      parts: finals.map((f, i) => ({
329|        scene: { id: ids[i] ?? "", ...f.base } satisfies Scene,
330|        emotion: f.emotion,
331|      })),
332|      entries,
333|    };
334|  });
335|
336|  const byId = new Map(splitScenes.filter((s) => s !== null).map((s) => [s.scene.id, s]));
337|  const scenes: AnalyzedScene[] = [];
338|  const entries: ResplitEntry[] = [];
339|  for (const old of analysisFile.scenes) {
340|    const split = byId.get(old.id);
341|    if (!split) {
342|      scenes.push(old);
343|      continue;
344|    }
345|    entries.push(...split.entries);
346|    for (const part of split.parts) scenes.push({ ...part.scene, ...part.emotion });
347|  }
348|  scenes.sort((a, b) => a.start_n - b.start_n);
349|  const seen = new Set<string>();
350|  for (const s of scenes) {
351|    if (seen.has(s.id)) throw new Error(`resplit minted duplicate scene id ${s.id}`);
352|    seen.add(s.id);
353|  }
354|  const problems = validateBookCoverage(book, scenes);
355|  if (problems.length > 0) throw new Error(`resplit breaks coverage: ${problems.map((p) => p.message).join("; ")}`);
356|
357|  usage.meta.costUsd = metaCostUsd({ prompt: usage.meta.promptTokens, cached: usage.meta.cachedTokens, completion: usage.meta.completionTokens });
358|  const jevCost = jevCostUsd(usage.jevInputTokens);
359|  const prevJev = analysisFile.provenance.jev;
360|  const prevMeta = analysisFile.provenance.meta;
361|  const segmentMeta = scenesFile.provenance.meta;
362|  writeFileSync(
363|    join(ctx.dir, "scenes.json"),
364|    `${JSON.stringify({
365|      bookId: book.id,
366|      textVersion: book.textVersion,
367|      scenes: scenes.map(({ id, ch, start_n, end_n, title, summary, characters }) => ({ id, ch, start_n, end_n, title, summary, characters })),
368|      provenance: {
369|        date: new Date().toISOString(),
370|        meta: {
371|          model: segmentMeta.model,
372|          requests: segmentMeta.requests + usage.meta.requests,
373|          prompt_tokens: segmentMeta.prompt_tokens + usage.meta.promptTokens,
374|          cached_tokens: segmentMeta.cached_tokens + usage.meta.cachedTokens,
375|          completion_tokens: segmentMeta.completion_tokens + usage.meta.completionTokens,
376|          cost_usd: segmentMeta.cost_usd + usage.meta.costUsd,
377|        },
378|      },
379|    })}\n`,
380|  );
381|  const totalJev = { model: deps.jev.model, requests: prevJev.requests + usage.jevRequests, input_tokens: prevJev.input_tokens + usage.jevInputTokens, output_tokens: prevJev.output_tokens + usage.jevOutputTokens, cost_usd: prevJev.cost_usd + jevCost };
382|  const totalMeta = {
383|    model: prevMeta.model,
384|    requests: prevMeta.requests + usage.meta.requests,
385|    prompt_tokens: prevMeta.prompt_tokens + usage.meta.promptTokens,
386|    cached_tokens: prevMeta.cached_tokens + usage.meta.cachedTokens,
387|    completion_tokens: prevMeta.completion_tokens + usage.meta.completionTokens,
388|    cost_usd: prevMeta.cost_usd + usage.meta.costUsd,
389|  };
390|  const overrides = scenes.filter((s) => s.muse_override !== null).length;
391|  const resplitWrote = resplitInputOf(scenes, book.textVersion);
392|  writeFileSync(
393|    join(ctx.dir, "analysis.json"),
394|    `${JSON.stringify({
395|      bookId: book.id,
396|      textVersion: book.textVersion,
397|      scenes,
398|      override_rate: scenes.length > 0 ? overrides / scenes.length : 0,
399|      provenance: {
400|        date: new Date().toISOString(),
401|        jev: totalJev,
402|        meta: totalMeta,
403|        total_cost_usd: totalJev.cost_usd + totalMeta.cost_usd,
404|        input: classifyInputOf(scenes, book.textVersion),
405|        resplit: {
406|          input: resplitWrote,
407|          auto_margin: RESPLIT_AUTO_MARGIN,
408|          ask_margin: RESPLIT_ASK_MARGIN,
409|          candidates: candidates.length,
410|          windows_classified: windowsClassified,
411|          splits: entries,
412|          merged_back: mergedBack,
413|          rejected: rejected,
414|          window_failures: windowFailures,
415|          muse_failures: museFailures,
416|          jev: { model: deps.jev.model, requests: usage.jevRequests, input_tokens: usage.jevInputTokens, output_tokens: usage.jevOutputTokens, cost_usd: jevCost },
417|          meta: { model: usage.meta.model, requests: usage.meta.requests, prompt_tokens: usage.meta.promptTokens, cached_tokens: usage.meta.cachedTokens, completion_tokens: usage.meta.completionTokens, cost_usd: usage.meta.costUsd },
418|        },
419|      },
420|    })}\n`,
421|  );
422|  return scenes;
423|}

