15|  meadow: { calma: 0.8, alegria: 0, tristeza: 0.2, suspenso: 0, misterio: 0, aventura: 0, combate: 0, asombro: 0, unknown: 0 },
16|  storm: { calma: 0.2, alegria: 0, tristeza: 0, suspenso: 0, misterio: 0, aventura: 0, combate: 0.8, asombro: 0, unknown: 0 },
17|  uneasy: { calma: 0.62, alegria: 0, tristeza: 0, suspenso: 0, misterio: 0, aventura: 0, combate: 0.38, asombro: 0, unknown: 0 },
