23|  const dir = mkdtempSync(join(tmpdir(), "resplit-"));
24|  const paragraphs = [para(1, "meadow"), para(2, "meadow"), para(3, "storm"), para(4, "storm"), para(5, "uneasy"), para(6, "uneasy"), para(7, "tense"), para(8, "tense"), para(9, "quiet"), para(10, "quiet")];
25|  writeFileSync(
26|    join(dir, "book.json"),
27|    JSON.stringify({ id: "oz", title: "Oz", author: "A", source: { gutenberg: 55, url: "u" }, textVersion: "sha256:x", chapters: [{ ch: 1, title: "One", start_n: 1, end_n: 10 }], paragraphs }),
28|  );
29|  const scene = (id: string, start_n: number, end_n: number, vector: Record<string, number>) => ({
30|    id, ch: 1, start_n, end_n, title: id, summary: "s", characters: [],
31|    jev: null, muse_override: null, final: { vector, intensity: 0.5, tempo: 0.5 }, error: null,
