83|export async function runClassify(ctx: StepCtx, deps: { jev: JevClient; meta: MetaClient }): Promise<AnalyzedScene[]> {
84|  const book = JSON.parse(readFileSync(join(ctx.dir, "book.json"), "utf8")) as Book;
85|  const scenesFile = JSON.parse(readFileSync(join(ctx.dir, "scenes.json"), "utf8")) as {
86|    scenes: Scene[];
87|    provenance: { meta: { model: string; requests: number; prompt_tokens: number; cached_tokens: number; completion_tokens: number; cost_usd: number } };
88|  };
89|  const outPath = join(ctx.dir, "analysis.json");
90|  const keys = classifyKeys(ctx.dir);
91|  if (decide(ctx.force, keys.recorded, keys.current).reuse) {
92|    return (JSON.parse(readFileSync(outPath, "utf8")) as { scenes: AnalyzedScene[] }).scenes;
93|  }
94|  const metaUsage: ClassifyMetaUsage = { model: deps.meta.model, requests: 0, promptTokens: 0, cachedTokens: 0, completionTokens: 0, costUsd: 0 };
95|  const byN = new Map(book.paragraphs.map((p) => [p.n, p]));
96|  const chapterTitle = new Map(book.chapters.map((c) => [c.ch, c.title]));
97|  let resplit: unknown;
98|  try {
99|    resplit = (JSON.parse(readFileSync(outPath, "utf8")) as { provenance?: { resplit?: unknown } }).provenance?.resplit;
100|  } catch {
101|    resplit = undefined; // no previous analysis yet
102|  }
103|  let jevInputTokens = 0;
104|  let jevOutputTokens = 0;
105|  let jevRequests = 0;
106|  const scenes = await runPool(scenesFile.scenes, 4, async (scene) => {
107|    const texts: string[] = [];
108|    for (let n = scene.start_n; n <= scene.end_n; n++) texts.push(byN.get(n)?.text ?? "");
109|    const emotion = await classifyScene(scene, texts.join("\n"), book.title, chapterTitle.get(scene.ch) ?? "", deps, metaUsage);
110|    if (emotion.jev) {
111|      jevInputTokens += emotion.jev.input_tokens;
112|      jevOutputTokens += emotion.jev.output_tokens;
113|      jevRequests += 1;
114|    }
115|    return { ...scene, ...emotion };
116|  });
117|  metaUsage.costUsd = metaCostUsd({ prompt: metaUsage.promptTokens, cached: metaUsage.cachedTokens, completion: metaUsage.completionTokens });
118|  const jevCost = jevCostUsd(jevInputTokens);
119|  const segment = scenesFile.provenance.meta;
120|  const metaTotal = {
121|    model: deps.meta.model,
122|    requests: segment.requests + metaUsage.requests,
123|    prompt_tokens: segment.prompt_tokens + metaUsage.promptTokens,
124|    cached_tokens: segment.cached_tokens + metaUsage.cachedTokens,
125|    completion_tokens: segment.completion_tokens + metaUsage.completionTokens,
126|    cost_usd: segment.cost_usd + metaUsage.costUsd,
127|  };
128|  // A resplit record describes the ranges it was written from; keep it
129|  // only when it still describes the scenes just written.
130|  const carried = (resplit as { input?: unknown } | undefined)?.input === resplitInputOf(scenes, book.textVersion) ? resplit : undefined;
131|  const seen = new Set(scenes.map((s) => s.id));
132|  if (seen.size !== scenes.length) throw new Error("classify found duplicate scene ids");
133|  const overrides = scenes.filter((s) => s.muse_override !== null).length;
