137|      bookId: book.id,
138|      textVersion: book.textVersion,
139|      scenes,
140|      override_rate: scenes.length > 0 ? overrides / scenes.length : 0,
141|      provenance: {
142|        date: new Date().toISOString(),
143|        jev: { model: deps.jev.model, requests: jevRequests, input_tokens: jevInputTokens, output_tokens: jevOutputTokens, cost_usd: jevCost },
144|        meta: metaTotal,
145|        total_cost_usd: jevCost + metaTotal.cost_usd,
146|        input: keys.current,
147|        ...(carried !== undefined ? { resplit: carried } : {}),
148|      },
149|    })}\n`,
150|  );
151|  return scenes;
